select sub.REGIST_SEQNO, sub.SUBMIT_SEQ, sub.PROD_ID, sub.ISSUE_PARTY_ID, sub.PRD_REGIST_CODE, sub.TERMID, sub.VALUE_DATE, sub.ASSET_ID, sub.POS_TYPE, sub.INTER_LEVE_NO, sub.INTER_ASSET_TYPE, sub.INTER_ASSET_CODE, sub.SUBJECT_NAME, sub.AMT, sub.CNY_AMT, sub.FLOAT_INGPL, sub.CNY_FLOAT_INGPL, sub.UNIT_VALUE_CPRICE, sub.UNIT_VALUE_FPRICE, sub.QTY, sub.CCY, sub.REMARK, sub.BALANCE_AMT, sub.VALUE_REG_DATE, sub.SEND_STATUS, sub.STATUS_DATE, sub.STATUS, sub.CHB_SUBMIT_DEADLINE, sub.SUBMIT_DEADLINE, sub.SUBMIT_TIME, sub.SUBMIT_FEEDBACK_STATUS, sub.CREATE_DEPT, sub.CREATE_USER, sub.CREATE_TIME, sub.UPDATE_USER, sub.UPDATE_TIME from CHB_AST_POS_SUB sub where 1=1
