select a.REGIST_SEQNO from (
SELECT
@rownum:=@rownum+1 rownum,
REGIST_SEQNO,
IF( (@prod_id = a.prod_id  and  @asset_id = a.asset_id and @inter_asset_code = a.inter_asset_code ), @rank := @rank + 1, @rank := 1 ) AS myrank,
@prod_id := a.prod_id,
@asset_id = a.asset_id,
@inter_asset_code = a.inter_asset_code
FROM
( SELECT * FROM CHB_AST_POS_SUB_HIS  ORDER BY  ifnull( UPDATE_TIME, CREATE_TIME ) DESC) a,
( SELECT @rownum := 0, @prod_id := NULL, @rank := 0 )b
where

    prod_id = #{item.prodId,jdbcType=VARCHAR}
    and asset_id = #{item.assetId,jdbcType=VARCHAR}
    and inter_asset_code = #{item.interAssetCode,jdbcType=VARCHAR}

)a
where 1=1    and a.myrank=1

